CREATE TRIGGER "account_password_invalidate_proofs" AFTER UPDATE OF "password" ON "account"
WHEN NEW."password" IS NOT OLD."password"
BEGIN
    DELETE FROM "emailChallenge" WHERE "userId" = NEW."userId";
    DELETE FROM "verification" WHERE "value" = NEW."userId" AND "identifier" LIKE 'reset-password:%';
END

CREATE TRIGGER "oauthClient_uri_sync" AFTER UPDATE OF "metadata", "postLogoutRedirectUris" ON "oauthClient"
BEGIN
    DELETE FROM "oauthClientUri" WHERE "clientId" = NEW."clientId";
    INSERT OR IGNORE INTO "oauthClientUri" ("clientId", "kind", "value")
        SELECT NEW."clientId", 'redirect-origin', value
        FROM json_each(COALESCE(json_extract(NEW."metadata", '$.loginflareRedirectOrigins'), '[]'));
    INSERT OR IGNORE INTO "oauthClientUri" ("clientId", "kind", "value")
        SELECT NEW."clientId", 'post-logout-uri', value
        FROM json_each(COALESCE(NEW."postLogoutRedirectUris", '[]'));
END

CREATE TRIGGER "site_branding_logo_changed" AFTER UPDATE OF "logoId" ON "siteBranding"
WHEN OLD."logoId" IS NOT NEW."logoId"
BEGIN
    UPDATE "brandLogo" SET "deleteAfter" = CAST(unixepoch('subsec') * 1000 AS INTEGER) + 3600000 WHERE "id" = OLD."logoId";
    UPDATE "brandLogo" SET "deleteAfter" = NULL WHERE "id" = NEW."logoId";
END

-- Account recovery, password changes and account suspension invalidate pending work.
CREATE TRIGGER "social_password_changed" AFTER UPDATE OF "password" ON "account"
WHEN OLD."password" IS NOT NEW."password"
BEGIN
    DELETE FROM "verification" WHERE "identifier" LIKE '2fa-%' AND "value" = NEW."userId";
    DELETE FROM "verification" WHERE "identifier" LIKE 'social-mfa:%' AND "value" IN (SELECT "id" FROM "socialFlow" WHERE "userId" = NEW."userId");
    DELETE FROM "socialFlow" WHERE "userId" = NEW."userId";
    DELETE FROM "securityProof" WHERE "userId" = NEW."userId";
END

CREATE TRIGGER "social_password_added" AFTER INSERT ON "account"
WHEN NEW."providerId" = 'credential' AND NEW."password" IS NOT NULL
BEGIN
    DELETE FROM "verification" WHERE "identifier" LIKE '2fa-%' AND "value" = NEW."userId";
    DELETE FROM "verification" WHERE "identifier" LIKE 'social-mfa:%' AND "value" IN (SELECT "id" FROM "socialFlow" WHERE "userId" = NEW."userId");
    DELETE FROM "socialFlow" WHERE "userId" = NEW."userId";
    DELETE FROM "securityProof" WHERE "userId" = NEW."userId";
END

CREATE TRIGGER "social_account_suspended" AFTER UPDATE OF "banned" ON "user"
WHEN NEW."banned" = 1
BEGIN
    DELETE FROM "verification" WHERE "identifier" LIKE '2fa-%' AND "value" = NEW."id";
    DELETE FROM "verification" WHERE "identifier" LIKE 'social-mfa:%' AND "value" IN (SELECT "id" FROM "socialFlow" WHERE "userId" = NEW."id");
    DELETE FROM "socialFlow" WHERE "userId" = NEW."id";
    DELETE FROM "securityProof" WHERE "userId" = NEW."id";
END

CREATE TRIGGER "oauthConsent_account_delete" AFTER DELETE ON "oauthConsent"
BEGIN
    UPDATE "oauthGrantPolicy" SET "revokedAt" = strftime('%Y-%m-%dT%H:%M:%fZ', 'now')
        WHERE "userId" = OLD."userId" AND "clientId" = OLD."clientId" AND "revokedAt" IS NULL;
    DELETE FROM "verification" WHERE "identifier" IN (
        SELECT "authorizationCodeId" FROM "oauthGrantPolicy" WHERE "userId" = OLD."userId" AND "clientId" = OLD."clientId"
    );
    DELETE FROM "oauthAccountApplication" WHERE "userId" = OLD."userId" AND "clientId" = OLD."clientId"
        AND NOT EXISTS (SELECT 1 FROM "oauthConsent" WHERE "userId" = OLD."userId" AND "clientId" = OLD."clientId");
    INSERT INTO "oauthAccountApplication" ("userId", "clientId", "scopes", "createdAt")
    SELECT c."userId", c."clientId",
        (SELECT json_group_array("value") FROM (
            SELECT DISTINCT j."value" FROM "oauthConsent" other, json_each(other."scopes") j
            WHERE other."userId" = OLD."userId" AND other."clientId" = OLD."clientId" ORDER BY j."value"
        )), max(coalesce(c."updatedAt", c."createdAt"))
    FROM "oauthConsent" c WHERE c."userId" = OLD."userId" AND c."clientId" = OLD."clientId"
    GROUP BY c."userId", c."clientId"
    ON CONFLICT ("userId", "clientId") DO UPDATE SET "scopes" = excluded."scopes", "createdAt" = excluded."createdAt";
END

-- The native provider remains authoritative for resource/audience and client
-- capability validation. Project business scopes into its existing tables.
CREATE TRIGGER "apiPermission_created" AFTER INSERT ON "apiPermission"
BEGIN
    UPDATE "oauthResource" SET "allowedScopes" = (
        SELECT json_group_array("scope") FROM (
            SELECT value AS "scope" FROM json_each('["openid","profile","email","offline_access"]')
            UNION SELECT "scope" FROM "apiPermission" WHERE "resourceId" = NEW."resourceId"
        )
    ) WHERE "id" = NEW."resourceId";
    UPDATE "oauthClient" SET "scopes" = (
        SELECT json_group_array(value) FROM (SELECT value FROM json_each("oauthClient"."scopes") UNION SELECT NEW."scope")
    ), "managementUserId" = (SELECT "userId" FROM "apiAccessWrite" WHERE "id" = 'access'),
    "managementSessionId" = (SELECT "sessionId" FROM "apiAccessWrite" WHERE "id" = 'access'), "managementAdministrator" = 1
    WHERE "clientId" IN (SELECT "clientId" FROM "oauthClientResource" WHERE "resourceId" = (SELECT "identifier" FROM "oauthResource" WHERE "id" = NEW."resourceId"));
END

CREATE TRIGGER "apiPermission_removed" AFTER DELETE ON "apiPermission"
BEGIN
    UPDATE "oauthResource" SET "allowedScopes" = (
        SELECT json_group_array("scope") FROM (
            SELECT value AS "scope" FROM json_each('["openid","profile","email","offline_access"]')
            UNION SELECT "scope" FROM "apiPermission" WHERE "resourceId" = OLD."resourceId"
        )
    ) WHERE "id" = OLD."resourceId";
    UPDATE "oauthClient" SET "scopes" = (SELECT json_group_array(value) FROM json_each("oauthClient"."scopes") WHERE value <> OLD."scope"),
    "managementUserId" = (SELECT "userId" FROM "apiAccessWrite" WHERE "id" = 'access'),
    "managementSessionId" = (SELECT "sessionId" FROM "apiAccessWrite" WHERE "id" = 'access'), "managementAdministrator" = 1
    WHERE "clientId" IN (SELECT "clientId" FROM "oauthClientResource" WHERE "resourceId" = (SELECT "identifier" FROM "oauthResource" WHERE "id" = OLD."resourceId"));
END

